		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462} fica nas colinas do sudeste: use a {item:279996} ao lado dele.",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} espera na Taberna do Javatusco Saltitante, em {object:2100}; ele e seus dois capangas lutam com você, mas param quando derrotados.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} treina guerreiros em {object:2100}, ao lado da Taberna do Javatusco Saltitante. {npc:6236} espera em {area:720}, em {zone:1413}, no caminho para {area:392}, bem mais tarde (40-50/01).",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: para {npc:2104}",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455} não tem instrutor de druidas: treine com {npc:5504} em {zone:1453} antes do metrô.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort {npc:5644}"] = "Escolte {npc:5644}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Siga a estrada para o oeste, passando por {area:460} (Horda), e para o sudoeste por {area:465} até {zone:1443}; {area:608} fica no alto do desfiladeiro.",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "O irmão dela, {npc:5643} (36), anda pela fortaleza com os sectários da Lâmina Ardente (30-33): puxe-o sozinho. {npc:13019} guarda o cetro no prédio principal da fortaleza.",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Leve {npc:5644} para fora da fortaleza; ela vai embora quando vocês saírem. {npc:5642} recebe a entrega em {area:608}, no fim do guia.",
		["Malem chest"] = "Baú de Malem",
		["Out of Thunder Axe Fortress"] = "Para fora da Fortaleza Machado do Trovão",
		["Scorpashi venom"] = "Peçonha de Scorpachi",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Os Kolkar vagam pelas planícies ao redor de {area:609}; as orelhas deles são para {npc:5752}.",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "Os escorpídeos Escorpachi caçam nas colinas ao redor de {area:2407}, na estrada para o sul.",
		["The chest lies in the ruins south-west of {area:608}."] = "O baú está nas ruínas a sudoeste de {area:608}.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "Use o {item:13892} de {npc:11596} num {npc:4700} e leve o kodo domado até o acampamento dele, cinco vezes; Kodos Idosos também soltam os pelegos.",
		["{item:190309}, north of {area:413}"] = "{item:190309}, ao norte de {area:413}",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "O acampamento de {npc:11596} fica na estrada ao sul de {area:609}, perto de {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "A torre de {npc:11863} fica no morro a oeste de {area:599}: pegue a missão dele primeiro; o cetro que ele quer está na fortaleza.",
		["{npc:5643} and the Seer"] = "{npc:5643} e o Vidente",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} se esconde na fortaleza da Lâmina Ardente, a sudoeste de {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "Bastão de Transformação de Dartol",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Siga a estrada para leste até os acampamentos de sátiros de {area:429}; {npc:3920} se esconde na borda deles.",
		["Lightforge Ingots"] = "Lingotes da Forja de Luz",
		["Melyria and {npc:3901}"] = "Melyria e {npc:3901}",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "Pegue o túnel para {area:419}; o tomo está nas ruínas no extremo oeste.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Os murlocs Guelrazul na praia a sudoeste de Menethil carregam os lingotes.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "Os Ancientes Enlouquecidos e Ancientes Fenescidos ao norte do poço lunar carregam a {item:5475}; o baú gasto que ela abre fica entre eles.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "O segundo {object:19901} fica no vale de {area:428}, no caminho para oeste.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "O santuário fica na colina logo a sudeste do poço lunar; suba pela trilha sinuosa.",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}, o posto avançado dos elfos noturnos no extremo leste da estrada: {npc:3848} fica lá.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}, um furbolg intocado pela corrupção, fica ao sul da estrada abaixo de {area:421}.",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619} lidera os sátiros de {area:429}; ele carrega o galho.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: para {npc:3961} em {area:415}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "De volta ao sul, passando Rosarães: Panteras e Raptores-do-espinhaço correm nas clareiras a oeste do acampamento, rumo à costa; os tigres anciões dominam as colinas a sudoeste.",
		["Both roam the grass around the camp and along the road north."] = "Os dois vagam pelo capim ao redor do acampamento e ao longo da estrada para o norte.",
		["Down to {area:35}"] = "Descendo até {area:35}",
		["Druid training"] = "Treinamento de druida",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Siga a estrada principal para o sul por toda a selva, passando o desvio para {object:3202}, até {area:35}, no cabo ao sul.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Siga a costa oeste para o norte; a ilha assombrada fica perto da praia, a oeste do acampamento de Rosarães. Basta chegar lá.",
		["For Archmage Ansirem in {zone:1416}"] = "Para o Arquimago Ansirem, em {zone:1416}",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "De {zone:1431}, pegue a estrada para o sul até a Selva do Espinhaço; as barracas dos caçadores ficam logo a oeste da estrada, depois do desvio para {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Glubglub, um murloc raro na costa a oeste do acampamento, deixa cair {item:4614}: pegue se encontrá-lo",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Os registros de Herodes ficam numa cabana no lado oeste do complexo; o cofre dele fica mais a leste, junto à entrada da caverna.",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "Percorra as ruínas trolls do norte e do centro: cada uma guarda uma tabuleta de pedra das lendas trolls. Panteras Umbragorja rondam furtivas na selva ao redor; o acampamento da Empreendimentos S.A. em {area:37} carrega os Cristais Rolados.",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores e tigres anciões",
		["River Crocolisks swim the river by the {area:99}."] = "Crocoliscos do Rio nadam no rio junto a {area:99}.",
		["River crocolisks"] = "Crocoliscos do Rio",
		["Skullsplitter trolls"] = "Trolls Rachacrânio",
		["Snapjaw Crocolisks"] = "Crocoliscos Arapuca",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "Crocoliscos Arapuca tomam sol na praia e nas ilhas ao longo da costa ao norte de {area:35}.",
		["Stranglethorn Tigers"] = "Tigres-do-espinhaço",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Pegue a estrada para o norte; {npc:738} patrulha nela, e o acampamento fica nas colinas a oeste.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Os rebeldes de Kurzen dominam o complexo a leste de {area:99}; trabalhe pela borda externa, onde ficam os Guerrilheiros da Selva e os Curandeiros, e saqueie os caixotes de suprimentos junto às barracas.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Os trolls Rachacrânio dominam as ruínas a leste da estrada, entre Rosarães e {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Os tigres adultos rondam as colinas logo ao sul e a oeste do acampamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Os tigres anciões ficam para depois, na volta de {area:99}",
		["The haunted island"] = "A ilha assombrada",
		["The jungle ruins"] = "As ruínas da selva",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "O minério cai dos kobolds Bigodesseco em {zone:1417}",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "Turgo patrulha a estrada ao norte do acampamento, rumo a {area:99}.",
		["Young tigers and panthers"] = "Tigres e panteras jovens",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de um caixote de {object:263}",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, no andar de cima da taberna",
		["{npc:469}, in the hut"] = "{npc:469}, na cabana",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, de {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} coleciona {item:2755}: as páginas caem de quase todo humanoide da selva. Transforme as páginas em capítulos pelo caminho.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} e os raptores Batecauda",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, o grande tigre, tem seu covil no alto da colina a sudoeste do acampamento; Raptores Batecauda correm ao sul dele, no caminho para {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, na taberna",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: para {npc:773}, em {area:35}",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: basta olhar em volta do acampamento dos caçadores",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "Um {npc:2434} espreita invisível na borda de {area:271}; mate-o e leia o contrato que ele carrega.",
		["Crushridge ogres"] = "Ogros Massacristas",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Para leste pela estrada até o {area:76}. Os {npc:256028} deixam cair os cristais; Noboru anda pelas ruínas e deixa cair sua borduna.",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["Fly to {zone:1453}"] = "Voar para {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Siga a estrada para leste saindo de {area:287}, passando a {area:1057}, até o {area:320}.",
		["Follow the road north to the draenei of the {area:657}."] = "Siga a estrada para o norte até os draeneis do {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} em {zone:1453}: guarde-o",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} em {area:35}: guarde-o",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} em {area:35}: guarde-o",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} em {area:271}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "Siga para o norte, passando a {area:314}; os estilhaços brilham na colina junto ao {area:333}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Só se Glubglub lhe deu o pingente no Espinhaço",
		["Phizzlethorpe"] = "Bruzundanga",
		["South-east along the loch to the dig site."] = "Para sudeste ao longo do lago até o sítio de escavação.",
		["Subdue the succubus"] = "Subjugue a súcubo",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Os ogros Massacristas ocupam as colinas ao norte de {area:280}. Mais ao norte, um baú de madeira gasto guarda o {item:3706}; {npc:2320}, do {quest:537}, fica bem ao lado.",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "Os trolls Cascasseca vivem nas colinas ao sul da {area:314}; os Mandingueiros ficam na aldeia, os Caçadores Sombrios guardam o fundo do vale.",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "A mensageira anda pela estrada a oeste da {area:314} com dois guardas; atraia-os para fora da estrada.",
		["The shards lie at the far end of {area:318}."] = "Os estilhaços estão no fundo do {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Os dois naufrágios ficam na baía a oeste da enseada. As cartas náuticas e os diários estão dentro deles; as gemas estão no fundo do mar em volta. Nagas Espinhadaga nadam pela baía inteira.",
		["The western swamp"] = "O pântano oeste",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Para oeste pela costa até a enseada dos goblins; Lolo vigia das pedras acima dela.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jovens, Tece-mágoas e Jaguares do Pântano vagam pelo pântano em volta da estrada.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} para o manto de {npc:2438}, de {npc:2381}, se você não tiver",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Massacrista",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, na estrada do {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Catedral da Luz",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, na Biblioteca Real da fortaleza",
		["{npc:185335}, at the same circle"] = "{npc:185335}, no mesmo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: três bichinhos para capturar em Arathi, {zone:1443} e no Espinhaço",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: capture-o, para {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} e {npc:2713}",
		["{npc:2713}'s errand"] = "A tarefa de {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, um ogro mago, ocupa a caverna no extremo sul do vale Cascasseca.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está preso numa jaula no extremo norte do santuário. Liberte-o e mantenha-o vivo na saída; o cofre dele aparece depois junto à estrada.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula o íncubo a você",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera no porão do {object:2164}, no {object:2101}. Use o {item:6913} no círculo de evocação de lá e derrote a súcubo que ele chama. Se você pegou {quest:65602}, entregue também a {item:190309} a ele, coloque-a no mesmo círculo e derrote o íncubo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, se você a pegou",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Follow the road north to {area:608}."] = "Siga a estrada para o norte até {area:608}.",
		["Follow the road south to {area:2407}."] = "Siga a estrada para o sul até {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Siga a estrada para o oeste pelo norte de {zone:1443} até as ruínas de {area:2405}. A torre de {npc:11863} fica no morro dali, a caminho do naufrágio.",
		["Maraudine centaurs"] = "Centauros Maraudinos",
		["Rock Elementals"] = "Elementais da Rocha",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "A próxima tarefa de Ryedol é em {area:1517}: pule.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Os centauros Maraudinos ocupam {area:607}, a oeste do cemitério; todos os tipos soltam os totens.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Os Elementais da Rocha vagam a sudeste de {npc:2921}; Urubus Gigantes e Coiotes Anciões do Rochedo dividem a planície a oeste deles.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Os anões de Umbraforja acampam logo ao norte da escavação; o Mapa Amassado está entre as barracas. Escavadores e Tecetrevas carregam a picareta de Ryedol. Coiotes do Rochedo vagam pelas encostas ao redor.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Os mariscos ficam no litoral noroeste da Selva do Espinhaço, no próximo guia: guarde-a",
		["The excavation crate"] = "O caixote da escavação",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "O baú do navio naufragado está na praia, logo a oeste da torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Ilha Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Assoladores Mortos-vivos vagam pelos campos de ossos ao sul da Aldeia Magram, a leste das Ruínas de Mannoroc; no extremo sudeste, use o {item:15848} para atrair os Espectros Magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escolte {npc:12277} de volta ao cemitério",
		["for the Dustwallow loop in the next guide"] = "para o circuito do Pântano Vadeoso no próximo guia",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} em {zone:1455}: guarde-a",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} em {area:271}: guarde-a",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} em {zone:1455}: guarde-a",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "só se você tiver {item:2868} (feitas por ferreiros)",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, um chefe centauro, acampa no litoral noroeste, ao norte da torre de {npc:11863}.",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: capture-o, para My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, ao lado de {npc:2921}",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "O próximo teste de {npc:2921} exige equipamento fabricado: pule.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019} fica na beira de {area:596}, a sudoeste de {area:2407}; {object:176751} estão entre os esqueletos. Um {npc:217590} rasteja pelo cemitério: capture um com o Entomology Starter Kit e depois marque o objetivo.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Inácio \"Cascão\"",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4772} ensina Anões em {area:803}, a leste de {area:131}, na estrada para {zone:1432}, ao lado dos carneiros de {npc:1261}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:7954} ensina Gnomos em {area:189}, logo a leste de {area:131}, ao lado dos mecanostriders de {npc:7955}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["Bloodsail camp"] = "Acampamento da Vela Sangrenta",
		["Boat to {area:35}"] = "Barco para {area:35}",
		["Cold Eye Basilisks"] = "Basiliscos Olho Frio",
		["Defeat the challengers and {npc:6238}"] = "Derrote os desafiantes e {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Todo pirata da Vela Sangrenta deixa cair Rapé, e um deles leva o olho de {npc:2493}; os Espadachins andam pela praia logo ao norte da cidade. As cartas náuticas e as ordens estão no acampamento pirata em {area:43}, ao sul de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Qualquer seguidor de Zanzil pode deixar cair o preparado; {npc:2537} anda pelo sul do acampamento.",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "Siga a estrada para o leste de volta a Theramore. Tervosh, a Grã-senhora Jaina e os oficiais estão na torre e em {area:514}.",
		["Gorilla hills"] = "Colinas dos gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Entregue as presas e fique: vêm três ondas de gorilas, {npc:1514} por último. Lute com a vida cheia.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Saia da cidade pelo túnel e siga a costa para o norte; a carta está no acampamento da Vela Sangrenta, na praia, onde anda Duncan \"Bonitão\".",
		["MacKinley's next task sends you after elite ogres: skip it."] = "A próxima tarefa de MacKinley manda você atrás de ogros elite: pule-a.",
		["Mirefin murlocs"] = "Murlocs Lamapina",
		["Naga Explorers"] = "Exploradores Nagas",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "No caminho para o norte até {area:392}, {area:720} fica perto de {area:391}, ao sul da cidade: atravesse a pé o banco de areia. {npc:6236} manda quatro desafiantes e depois {npc:6238} (nível 33) contra você, um de cada vez.",
		["Paladin: {quest:1661}"] = "Paladino: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Volte para a cidade; Sacode fica na entrada do túnel.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Siga para o leste; os Horrores Emaranhados no caminho também deixam cair os ensaios. Procure na borda de {area:74}, onde as ruínas do templo saem da água.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Siga para o interior até as colinas dos gorilas do Vale da Névoa. Gorilas Anciões do Vale da Névoa deixam cair os miúdos; {npc:1449} fica entre eles.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Siga para o norte até as colinas a oeste da estrada. {npc:2535} e {npc:2536} ficam juntos, logo ao norte da aldeia de Zanzil.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "Siga para nordeste, passando o acampamento de Rosarães, e pegue a estrada para o norte até o acampamento no alto do vale. No caminho, uma {npc:217588} rasteja na selva a sudeste do acampamento de Rosarães: capture uma com o Entomology Starter Kit e marque-a.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Siga para noroeste a partir da mina até a baía na costa noroeste. Os Mariscos Gigantes ficam no fundo dela e guardam as pérolas; {npc:2624} nada entre eles e deixa cair {item:4034}.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Siga para o sul até a cabana do gigante, no meio do pântano.",
		["Riding at 40"] = "Montaria no nível 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "A próxima tarefa de Chifre do Mar volta para Arathi: pule-a.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Cascão espera a oeste do casarão, no brejo abaixo de {area:504}. Leve-o até as folhas de trevo aquático e afaste as criaturas do pântano dele.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "Pegue a estrada para o norte até o casarão em ruínas; Zé mora no barraco ao lado, e a terra solta fica no canto da casa.",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "Pegue o {area:2257} no {object:28027}. {npc:5637} fica no salão da Recuperação Ilimitada, junto a {object:32356}; {npc:1356}, no próprio salão; {npc:2786}, em {object:32383}. O próximo guia voa até {area:144}.",
		["The Bloodsail captains"] = "Os capitães da Vela Sangrenta",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "Os Basiliscos Olho Frio ficam nas rochas a oeste da mina.",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "Os murlocs Lamapina lotam a costa norte depois de {area:497}; complete as línguas nos quelônios ao lado deles.",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "Os capitães ficam nos navios ancorados perto de {area:43}, cada um com uma tripulação de piratas de nível 42-45: Tranquiláguas (45) e Querena (46) nos conveses mais próximos, {npc:2546} (48) na nau capitânia. No nível 42 é luta para grupo ou para o fim do guia; se for, limpe cada convés antes. O pergaminho de Cortello está no naufrágio junto à praia.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Os desertores acampam ao sul da estrada, a oeste da cabana de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "A madeira flutuante chega à praia ao longo da margem leste.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Os nagas vasculham as praias ao norte do acampamento da Vela Sangrenta; eles deixam cair os juncos.",
		["The north-west coast"] = "A costa noroeste",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "O próximo pergaminho da charada fica no oeste do Pântano Vadeoso: pule-o.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "O pergaminho fica no brejo ao norte de Biggs. Os Errantes do Pântano ao norte dele podem deixar cair os ensaios de Hadggar.",
		["The sunken temple"] = "O templo submerso",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "O ritual de Unbagwa",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Zanzil's village"] = "Aldeia de Zanzil",
		["for {area:1438}: keep it"] = "para {area:1438}: guarde",
		["for {npc:2616} in Theramore: keep it"] = "para {npc:2616}, em Theramore: guarde",
		["for {npc:5635} at {area:348}: keep it"] = "para {npc:5635}, em {area:348}: guarde",
		["for {npc:770} at the {area:99}, on the northern loop"] = "para {npc:770}, em {area:99}, no circuito norte",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "só se você tiver uma {item:3853} (criação de ferreiro)",
		["with the spices from Theramore"] = "com os temperos de Theramore",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cozinha em {object:2169}; {npc:5384} fica em {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: outras cores, 20g",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, na Biblioteca Real, em {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, de 30-40/05-arathi-highlands",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: capture-a, para {quest:93176}",
		["{npc:2487}, top floor"] = "{npc:2487}, último andar",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "A próxima tarefa de {npc:2498} sobre Zanzil começa em {zone:1441}: pule-a.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} e {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada perto da costa noroeste, no circuito norte",
		["{npc:384}: other colours, 20g"] = "{npc:384}: outras cores, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, em {object:2164}: {npc:6251}, em {area:392}, recebe no fim do próximo guia",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: outras cores, 20g",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}: para {area:1438}, guarde",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, na Catedral da Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Em seguida, {npc:6236} oferece O vigia dos ventos (1791): a série da arma de Redemoinho, com um elite no fim, está no guia de classe de Guerreiro Arma do redemoinho.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864}, em {zone:1446}, guarde",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: outras cores, 20g",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} não tem instrutor de xamã",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Pérolas Azuis da Selva do Espinhaço",
		["Fly to {area:392}; {npc:6251} teaches in the house by the bank. Fly back to Theramore afterwards."] = "Voe para {area:392}; {npc:6251} ensina na casa junto ao banco. Depois volte voando para a Ilha Theramore.",
		["Raleigh's next errand is in the {area:796}: skip it."] = "A próxima tarefa de Raul é em {area:796}: pule.",
		["Ride back east to {area:1898}."] = "Volte a leste até {area:1898}.",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "Cavalgue para o norte até {area:144} e voe para {area:271}. {npc:3980} prega junto à estalagem.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Os Dragonetes Escaldantes fazem ninho na ravina a leste de {npc:2888}; deixe os Guardiões Flâmeos (elite) em paz. {item:4612} cai raramente: pegue se aparecer enquanto você farma.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "As duas primeiras jaulas ficam juntas na aldeia Cascasseca ao sul de {npc:5634}; a terceira está na aldeia seguinte, a leste. Qualquer troll Cascasseca pode soltar um colar.",
		["Theramore"] = "Ilha Theramore",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Witherbark villages"] = "Aldeias Cascasseca",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} fica nas docas onde o barco atraca.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "A próxima missão de {npc:2817} não dá experiência: pule.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "A próxima tarefa de {npc:2888} é uma caçada elite: pule.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa na estrada a leste de {area:348}.",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} continua pagando pelos colares: entregue os que sobrarem",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Volte a {area:1117}. Todo naga Cristafúria de lá pode deixar cair escamas.",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "Barco para {area:1108} e cavalgue para leste até {area:1105}. As missões de {npc:14637} na costa exigem nível 45.",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["Grimtotem tauren"] = "Taurens Temível Totem",
		["Grind to 45"] = "Farme até o 45",
		["Hatecrest naga"] = "Nagas Cristafúria",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Volte cavalgando para {area:1108}; o goblin fica junto à doca.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Volte para oeste pela estrada e depois para o norte até as colinas dos Yetis Cortifúria. Todo yeti daqui pode deixar cair um couro; um pode deixar cair um {quest:7735}, que {npc:7852} também paga.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cavalgue para leste até o acampamento Gordunni nas colinas a sudeste do vale dos yetis: Bruxos Gordunni e Xamãs Gordunni ocupam o acampamento, Brutamontes Gordunni vagam pelas encostas ao redor e mais ao norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cavalgue para o norte até o vale dos yetis. Todo Yeti Abominável pode deixar cair um couro grosso; {npc:5346} (nível 48) ronda o meio.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cavalgue para nordeste até o posto avançado dos elfos noturnos na fronteira de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cavalgue para sudeste até os gnolls Patábua; as mochilas do mensageiro estão no acampamento sul deles, e um pacote dentro delas inicia uma entrega para {area:489}. A colmeia Zukk'ash fica logo ao sul: lute até o casulo que prende Patiphe, o Mensageiro, liberte-o e mantenha-o vivo na saída.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Cavalgue para oeste até o gigante da montanha amistoso ao pé das colinas. Os Terrâmbulos e Gigantes do Penhasco ao redor dele são elite: mantenha distância.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Toque o sino sempre que {npc:7774} parar para vagar e leve-a para o sul até {npc:7765}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Costívagos, Fundívagos e Ondarilhos (gigantes elite) andam pela costa ao norte da doca: atinja um com {item:18904} e mate o gigante encolhido. Elementais do Mar e Borrifos do Mar flutuam na mesma rebentação.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Pegue o barco para {area:1108} e siga a costa para o sul até a Canoa Destruída na praia.",
		["The courier's boat"] = "O barco do mensageiro",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Caminhe para o sul pela ilha até as ruínas dos nagas; o mirante fica entre elas.",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "Você termina na doca de {area:1108}: o guia de {zone:1446} começa com a viagem para leste a partir daqui.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Murmuréolo em {zone:1457}: a rota leva você lá no 47",
		["{item:11463}, from the backpacks"] = "{item:11463}, das mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "As recargas de {npc:14637} são de nível 55: pule-as.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} então pede que você leve notícias a {zone:1457}: pule, {area:976} manda você lá em vez disso.",
		["{npc:3936}, beside him"] = "{npc:3936}, ao lado dele",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: a resposta dele espera em {area:702}, mais tarde",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} vaga pelas colinas ao norte de {npc:7765}, entre as harpias da Nascente Norte; o sino dela está no baú ao lado.",
		["{npc:7774}'s escort"] = "A escolta de {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, no alto do bastião",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} fica para o fim do circuito no continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Gives the {item:8585}"] = "Dá o {item:8585}",
		["He runs off to keep Rizzle busy"] = "Ele sai correndo para distrair o Rebu",
		["Hearth to {area:976}."] = "Use a Pedra de Regresso para {area:976}.",
		["Pool by {area:979}"] = "Lagoa junto a {area:979}",
		["Ride back west to {area:976}."] = "Cavalgue de volta para o oeste até {area:976}.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cavalgue para o leste pelas dunas até o porto goblin na costa nordeste.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Cavalgue para o noroeste até o acampamento dos trolls Zangareia em {area:979}. Use o {item:8584} na beira da lagoa; os trolls ficam perto, então puxe o mais próximo primeiro.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cavalgue para o sul até o acampamento de escavação em {area:1938}. {npc:7771} lhe entrega um elmo detector: use-o para ver os montes de {quest:3161}, espalhados pela areia ao redor do acampamento e a sudoeste, rumo aos ogros.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cavalgue para o sudoeste até o complexo dos ogros. Brutamontes Dunamalho e Impositores Dunamalho (46-48) o enchem; {npc:12046} (49) fica no meio, cercado de guardas: elimine-os primeiro.",
		["The Wanted poster beside him"] = "O cartaz de Procurado ao lado dele",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "A tartaruguinha {npc:5955} se esconde no extremo norte do vale. Leve-o para casa, até a esposa {npc:6015}, junto à água logo a leste de {area:977}: ele anda devagar e as feras do deserto vão atrás dele, então mantenha-o vivo.",
		["The pool by {area:979}"] = "A lagoa junto a {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "O mesmo cartaz: {npc:7847} vem bem mais tarde, depois de {area:976}",
		["The {area:1938}"] = "{area:1938}",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: a rota leva você lá no nível 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, no lado leste da cidade",
