		["Mark {npc:10902} with the {item:12815}"] = "Marque a {npc:10902} com a {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marque a {npc:10903} com a {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marque a {npc:10904} com a {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marque a {npc:10905} com a {item:12815}",
		["More watches"] = "Mais relógios",
		["Radley and Durgen"] = "Eiras e Durgen",
		["Ride back south to the camp."] = "Cavalgue de volta para o sul até o acampamento.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Cavalgue para o leste até o rio da fronteira: {npc:1855} mora numa pequena cabana na margem.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Cavalgue para o norte pela estrada até a Madeireira Beiranorte; {npc:11610} se esconde na borda do acampamento.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Cavalgue para o noroeste até a fazenda dos Dalson. O diário está no celeiro; um esqueleto errante carrega a chave da casinha, e {npc:10836} espera na casinha com a chave do armário.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cavalgue para o noroeste até {area:2276}, na borda de {area:2277}.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Cavalgue para o sul até {area:201}, onde {npc:11078} guarda o caldeirão.",
		["Ride south-west to the camp."] = "Cavalgue para o sudoeste até o acampamento.",
		["Ride west along the road to the hot springs."] = "Cavalgue para o oeste pela estrada até as fontes termais.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Cavalgue para o oeste até {area:2627}. Cães Pestilentos Miúdos, Quirópragos e Vermes Carniceiros vagam pelos bosques; encha a {item:15042} nos grandes cupinzeiros e mate os Cães Pestilentos Frenéticos mais ao norte.",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Pegue o barco para o continente e cavalgue para o nordeste até o acampamento de {npc:14637}, junto a {area:1119}.",
		["Ten {item:11040} from the {item:11020}"] = "Dez {item:11040} da {item:11020}",
		["The Andorhal watchtowers"] = "As torres de vigia de Andorhal",
		["The Scarlet Crusade"] = "A Cruzada Escarlate",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Socorristas Escarlates, Caçadores Escarlates, Cavaleiros Escarlates e Magos Escarlates patrulham a madeireira e a estrada rumo a {area:190}.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "O caldeirão fica em {area:202}, junto à fazenda de {npc:10739}.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "O caldeirão fica em {area:200}, a nordeste do Campo Pedravil; o Mestre da Caldeira dele fica ao lado.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Os gigantes encolhidos vagam por {area:1119}; os Elementais do Mar andam pela costa a oeste.",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Use o {item:12627} junto aos silos de grãos para atrair Parasitas Temporais. {quest:5154} é um dos Tomos Mofados na prefeitura. Todo esqueleto da cidade deixa cair {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Use a {item:12815} ao pé de cada uma das quatro torres de vigia na periferia de Andorhal, ao norte do acampamento.",
		["{area:190} overlook"] = "Mirante de {area:190}",
		["{area:199} cauldron"] = "Caldeirão de {area:199}",
		["{area:200} cauldron"] = "Caldeirão de {area:200}",
		["{area:201} cauldron"] = "Caldeirão de {area:201}",
		["{area:202} cauldron"] = "Caldeirão de {area:202}",
		["{item:12894}, at the monument"] = "{item:12894}, no monumento",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} está na prefeitura de {area:190}, a oeste de {npc:1855}: os guardas escarlates ficam bem juntos.",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955} está a leste do celeiro em {area:201}.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} espera na estalagem em ruínas no lado oeste de Andorhal.",
		["{npc:10739} stands by the farm at the {area:202}, north-east of the fields."] = "{npc:10739} fica junto à fazenda em {area:202}, a nordeste dos campos.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "O fantasma de {npc:10778} vaga junto à casa da fazenda de {area:199}, a oeste de {area:200}; o embrulho dela está lá dentro.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} e {npc:7740} ficam junto ao Templo da Lua; encha o {item:11682} no poço lunar lá dentro.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "A casa de fazenda de {npc:10927} fica na colina a leste do acampamento; o monumento de {npc:10936} fica logo ao norte dela.",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} guarda o caldeirão em {area:199}, a oeste de Andorhal.",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} é elite: recomenda-se ir em grupo",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} é elite de nível 61",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} em {area:976}: guarde",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, na costa ao norte da cidade",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: guarde para {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "O acampamento de {npc:7775} fica ao norte de {area:1119}. Ele vende o {item:11243} quando recebe a isca.",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, em {area:1658}",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, em {area:2268}: guarde",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, onde o próximo guia treina, não tem instrutor de druida",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Ruínas de Andorhal",
		["Angerclaw bears and Felpaw wolves"] = "Ursos Garraivosos e Lobos Patavil",
		["Araj is elite: grouping up is advised."] = "Araj, o Evocador, é elite: recomenda-se formar um grupo.",
		["Bronzebeard's Encampment"] = "Acampamento Barbabronze",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "Atravesse o rio a leste de {npc:1855} até {area:2627}. Os Espíritos da Várzea do Medo assombram o bosque ali.",
		["Fly to {area:976}."] = "Voe para {area:976}.",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Siga a estrada para o norte até {area:1767}. Os Pisoteadores de Ferrárbol carregam o coração; termine as garras nos Ursos-cinzentos Garraivosos e nos Assoladores Patavil do norte.",
		["Grind to 60"] = "Upe até o 60",
		["Hand him the ten texts you kept"] = "Entregue a ele os dez textos que você guardou",
		["Havunth's camp sits just west of {area:3425}."] = "O acampamento do Guardião do Crepúsculo Havunth fica logo a oeste de {area:3425}.",
		["Hearth to {area:392} and fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Regresse para {area:392} e voe para {area:976}. Compre duas Barras de Tório na Casa de Leilões daqui para {quest:5801}.",
		["Irontree Stompers"] = "Pisoteadores de Ferrárbol",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Guarde o {item:11169}, as garras e o coração que ele devolve",
		["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "Continue para o oeste pela estrada até o acampamento de {npc:9298}, ao lado das fontes termais.",
		["Ride back south along the road to the Sanctuary."] = "Volte para o sul pela estrada até o Santuário.",
		["Ride back south-east to the hermit."] = "Volte para o sudeste até o eremita.",
		["Ride back south-west to {area:3197}."] = "Volte para o sudoeste até {area:3197}.",
		["Ride back to {area:3137} and fly to {area:2255}."] = "Volte para {area:3137} e voe para {area:2255}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Siga para o leste até as colinas. Use o {item:11169} para invocar {quest:4005} e derrote-o para obter o totem.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Siga para o leste até as ruínas de {area:2738}. {object:179565} está entre os edifícios em ruínas, vigiado por Sentinelas Torturadas.",
		["Ride north along the west side to Mayna's small camp."] = "Siga para o norte pelo lado oeste até o pequeno acampamento da Tutora do Crepúsculo Mayna.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Siga para o norte até a aldeia dos furbolgs de Lenha Morta, perto da entrada da caverna de {area:1769}.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Siga para o norte até {area:541}. Use {npc:10980} ao lado de {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Siga a estrada para o norte até a serraria e coloque o barril de cupins no meio dela.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "Siga para o sudoeste até o acampamento dos anões perto das montanhas do sul e interrogue {npc:15171} e {npc:15170}. A Algibeira do {npc:15190} está na areia, logo a sudeste do acampamento.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Siga para o sudoeste até o acampamento de {npc:7771} em {area:1938}.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Fazer {area:2577} em {zone:1444} em vez de farmar leva você lá mais rápido em grupo. Pule esta etapa para farmar sozinho.",
		["Take the boat from {area:442} to {area:702}."] = "Pegue o barco de {area:442} para {area:702}.",
		["Take the flight path in {area:2361} and fly to {area:442}."] = "Pegue a rota de voo em {area:2361} e voe para {area:442}.",
		["Take the portal up to {zone:1457}."] = "Pegue o portal para subir até {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Pegue a estrada para o oeste, desça até a cratera e siga até a {area:540}, a caverna dos silitídeos no sul. {npc:10041} espera na câmara mais profunda.",
		["Ten more for {quest:8323}"] = "Mais dez para {quest:8323}",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "A escavação do Martelo do Crepúsculo ocupa o canto noroeste: há fragmentos de tábua no chão, e as Tempestades de Poeira e os Estrondores do Deserto também os carregam. Todo sectário pode deixar cair um {item:20404}: guarde vinte, dez para {npc:15306} e dez para {npc:15194} depois.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "O eremita se esconde entre as rochas a sudeste de {area:2738}.",
		["The {area:2479}"] = "{area:2479}",
		["The {area:3098}"] = "{area:3098}",
		["Twilight Tablet Fragments"] = "Fragmentos de Tabuleta do Crepúsculo",
		["Twilight's Hammer cultists"] = "Sectários do Martelo do Crepúsculo",
		["Use the jars on slain oozes"] = "Use as jarras nas gosmas mortas",
		["Wait a moment for {npc:9116}"] = "Espere um pouco por {npc:9116}",
		["{area:1770} braziers"] = "Braseiros de {area:1770}",
		["{area:2057} (optional)"] = "{area:2057} (opcional)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} é para os níveis 58 a 60; {quest:5505} é entregue em {area:3197}, abaixo.",
		["{area:2577} (optional)"] = "{area:2577} (opcional)",
		["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577} é para os níveis 55 a 60; farmar {npc:7446}, abaixo, leva você ao 59 sozinho.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} espera na estalagem em ruínas no lado oeste das Ruínas de Andorhal, a cidade em ruínas ao norte do acampamento. {npc:1852} protege o filactério dele no meio da cidade.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "O fantasma de {npc:10778} vagueia perto da casa da fazenda de {area:199}, a oeste das Ruínas de Andorhal. Os Carniçais Grasnantes do campo carregam a outra metade do amuleto: junte as duas metades.",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "A casa de {npc:11801} fica em {area:2361}, a leste de {npc:11939}.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} comanda o acampamento dos sectários no extremo sudoeste.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, em {object:2096}",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} é um elite de nível 61",
		["{npc:1855} (optional)"] = "{npc:1855} (opcional)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} Fordring vive numa pequena cabana à beira do rio da fronteira, a nordeste da madeireira. Entregue {quest:5781} se você a concluiu.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, no alto de {area:1658}",
		["{npc:4155}, in the bank"] = "{npc:4155}, no banco",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} em {zone:1457}: guarde-a",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}, no Templo da Lua",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, no fundo do refúgio",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} não tem instrutor de xamã",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Volte pelo túnel até a caverna de {npc:257597} acima da fazenda.",
		["Back to {area:77}"] = "De volta a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "De volta a {npc:257446} em {area:77}. Ele lhe dá a {item:6635}: pegue a trilha marcada por escombros que sobe para oeste a partir do sul do vale até a Pedra Espiritual na crista, beba a Sapta ao lado dela e fale com a {npc:5891}, depois leve o {item:6656} dela de volta a Teo.",
		["Back to {npc:257597}"] = "De volta a {npc:257597}",
		["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "Rochetuscos e Ursos Pretos Jovens vagam pelos campos em volta de {area:131} e da garagem.",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Cada missão de Grif Selvacuore lhe dá um {item:15908}: use-o na fera que ele indicar e depois leve o bastão de volta a ele na ferraria de {area:131}. Rochetuscos Grandes, Leopardos da Neve e Ursos Garra de Gelo vagam pelos campos logo ao sul e a leste de {area:131}.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa na crista que dá vista para a {area:134}, a oeste. Fale com ele para usar a vidência dele.",
		["Feather Charms, from the Frostmane Novices"] = "Patuás de Penas, dos Noviços Jubafria",
		["Firewood"] = "Lenha",
		["Follow the road east past the depot to {area:138}."] = "Siga a estrada para leste passando a garagem até o {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Siga a estrada para nordeste a partir de {area:131} até a garagem abaixo da estrada de {zone:1455}.",
		["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "Siga a estrada até {zone:1455} e treine com seu instrutor de classe. O {area:2257} sai da {object:171524}, no leste da cidade. Vá nele até {zone:1453}.",
		["From the {quest:2997} she gives you"] = "Do {quest:2997} que ela lhe dá",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Jovens Trolls Jubafria enchem as encostas ao sul e a leste do acampamento de {npc:786}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Pingentes de Urso Garrálgido, dos Jovens Trolls Jubafria nas encostas acima do acampamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Saia de {zone:1453} pelo portão principal, vá para o sul até {area:87} e para leste pela estrada até a {area:62}. {npc:881} (nível 9) fica junto à casa da fazenda.",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Gnomos Leprosos em volta da Aldeia da Cevada e da estrada de {area:133} levam as rodas dentadas e engrenagens. Ursos Garra de Gelo, Rochetuscos Anciões e Leopardos da Neve vagam pelas colinas em volta do lago.",
		["Level 4 spells, before Gozwin's camp"] = "Feitiços de nível 4, antes do acampamento de Gozwin",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Lobos Jovens Rotos vagam pela neve logo ao sul de {area:77}.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "Batecrânios Pedraqueixo enchem a pedreira; Emboscadores Pedraqueixo junto ao {area:212} deixam cair o {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Troggs Pedraqueixo e Troggs Pedraqueixo Parrudos cavam por todo o fundo do vale ao sul de {area:77}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Rochetuscos Pequenos pastam em volta do acampamento de {npc:714} e pelo lado oeste do vale.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Leopardos da Neve e javalis vagam pela neve entre o rancho e a pedreira. Ferreiros: Barras de Cobre vêm da fundição de {item:2770} ou dos mercadores de profissão.",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Videntes Lascapedra (nível 13) ficam entre os troggs no sul do {area:923}, ao sul de {npc:257808}; Geomantes Ratatúnel (nível 12) trabalham na {area:149}, no extremo norte do lago. Os troggs vêm em bandos e alguns atacam à distância: atraia um de cada vez.",
		["Subdue the voidwalker"] = "Subjugue o emissário do caos",
		["The Fire Spirit Stone"] = "A Pedra do Espírito de Fogo",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "O Rabo-de-galo Escaldante dura cinco minutos: vá direto para o norte até {npc:836} dentro de {area:77}.",
		["The boars"] = "Os javalis",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "A lenha está na neve em volta do lago congelado junto ao refúgio.",
		["The quarry troggs"] = "Os troggs da pedreira",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "O metrô chega no {object:28027}. {npc:5480} treina guerreiros em {object:2100}; {npc:6089} e {npc:6090} ficam juntos perto da {object:2152} de lá. {npc:6090} luta com você pela caneca dele.",
