		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Voe para {area:1237} se tiver a rota, senão para {area:431}, e caminhe para leste saindo de {zone:1440} até {zone:1447}.",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Voe para {area:3137} se tiver a rota, senão para {area:415}, e caminhe para leste saindo de {zone:1440} até {zone:1447}.",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Do oeste de {zone:1446} pegue a trilha que desce até {zone:1449}. {area:541}, no norte, é um acampamento neutro.",
