		["Ride east along the road to {area:2255}."] = "Siga a estrada para o leste até {area:2255}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Siga a estrada para o norte, passando por {area:1763}, até {area:1997}.",
		["South to the Sanctuary once more."] = "Volte mais uma vez para o sul até o Santuário.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Pedaços de Vinhavil, de {npc:11801}, pede {area:2577}. Pule.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "Depois {npc:9298} manda você atrás de {npc:10738}, um elite na caverna dele. Pule.",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Escorpídeos Encouraçados rastejam pelas planícies a oeste de {area:362}. Domestique um e volte até {npc:3171}.",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Volte para leste até a praia ao norte de {npc:275657}. Batedores Iralisca e Serviçais Iralisca ocupam a praia abaixo da {area:370}. Caçadores: domestiquem um {npc:3107} na praia.",
		["Back south to {area:362}."] = "Volte para o sul até {area:362}.",
		["Back to the Den"] = "De volta ao Covil",
		["Back to {area:362}."] = "De volta a {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Volte até {npc:5875} na {object:172960}. Use os {item:7464} no círculo de evocação de lá e derrote o emissário do caos para prendê-lo.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Sectários de Lâmina Ardente ocupam as cavernas de {quest:827}; qualquer um deles deixa cair um {item:4871}. {npc:3204}, um bruxo de nível 14, fica no fundo e deixa cair o {item:4903}.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Os Espreitadores Vis vagam pela encosta abaixo da caverna, no lado norte do vale.",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "Siga a estrada para o norte de {area:362} até o portão principal de {zone:1454}, logo a oeste da {area:817}. {npc:3352} fica com os instrutores de caçador no {object:172958}.",
		["Free {npc:275811} and see her safely out of the crag"] = "Liberte {npc:275811} e leve-a em segurança para fora do penedo",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Siga para o sul pelas ilhas. Os ídolos Loa estão espalhados pelas ilhas do sul; Trolls Vodu e Trolls Bagateados os guardam e derrubam os Pingentes Bagateados. {quest:826} e a jaula de Minshina ficam na ilha mais ao sul.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dentro da caverna, siga reto na primeira bifurcação, depois à direita, e acompanhe o riacho à sua esquerda até a cachoeira: a picareta brilha junto à água, atrás de uma coluna de pedra.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dentro da caverna, mantenha-se rente à parede da direita a volta toda, passando o riacho: {npc:3183} espera no fim.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "A cabana de Misha fica ao sul dos lagartos. Os crocoliscos ao longo do {area:814}, a oeste, carregam o {item:4891}.",
		["Prickly pears"] = "Figos-da-índia",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Javatuscos e batedores ocupam as cabanas a oeste da cidade; levanta-poeiras e guardas de batalha ocupam os acampamentos mais a oeste.",
		["Spitelash naga"] = "Nagas Iralisca",
		["Tame it with the {item:15908}"] = "Domestique-o com a {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "A fortaleza fica na costa a sudeste de {area:362}. O machado, o arco e o escudo dos saqueadores estão nos arredores dela. Marinheiros e fuzileiros derrubam os {item:4870}. {npc:3192} espera no alto da fortaleza; a chave dele abre o baú ao seu lado, que guarda o {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Os figos-da-índia crescem entre as cabanas dos javatuscos logo a oeste da cidade.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "As armas ficam em volta d'O Covil e do campo de treino; os Mosquetuscos vagam por todo o fundo do vale.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "O {object:58595} fica na {area:817}, entre os sectários que você acabou de enfrentar.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Lagartos Trovejantes e Pelegos de Relâmpago pastam no {area:369}, do outro lado da ponte; qualquer um deles pode derrubar uma {item:6486}.",
		["Thunder lizards across the river"] = "Lagartos trovejantes do outro lado do rio",
		["Training weapons and boars"] = "Armas de treino e javalis",
		["Wake {quest:5441} with the {item:16114}"] = "Acorde os {quest:5441} com o {item:16114}",
		["the {object:654925} on the ground beside her"] = "o {object:654925} no chão ao lado dela",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "O {area:366} fica a oeste de Sen'jin. Os três planos de ataque estão no chão entre as tendas dos centauros. {npc:275811} também está presa no penedo.",
		["{area:817}'s mouth"] = "Entrada da {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, onde você começa",
		["{npc:265809}'s campfire"] = "A fogueira de {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: só encantadores, o resíduo vem do desencantamento de Pingentes Bagateados",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} fica na praia a leste de {area:362}. O tridente, o estandarte e a adaga estão na areia em volta dele.",
		["{npc:3102} hooves"] = "Cascos de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de volta em {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, um gigante do mar elite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} fica logo na entrada da caverna; {npc:3159}, no fundo da caverna, atrás dele.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} espera dentro d'O Covil, a construção logo a oeste de {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, na torre de vigia",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, o instrutor de guerreiro ao lado d'O Covil",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, o instrutor de caçador ao lado d'O Covil",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, o instrutor de ladino n'O Covil",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, o instrutor de bruxo no fundo da caverna",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, o instrutor de xamã ao lado d'O Covil",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} está ferido no sopé das colinas a noroeste d'O Covil.",
		["{npc:3294}, by the inn"] = "{npc:3294}, junto à estalagem",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, a instrutora de mago, na entrada d'O Covil",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} fica do lado de fora d'O Covil. {area:639} é a colina logo ao sul: beba a {item:6635} lá para ver a {npc:5891}, depois leve o {item:6656} de volta para {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} e o seu {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, na {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} fica na estrada, na saída leste do vale.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, junto à fogueira de cozinhar",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} acampa na colina a oeste da praia dos nagas, ao sul da {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "O portão principal de {zone:1454} fica logo a oeste da {area:817}. {npc:5875} fica na {object:172960}, o cânion abaixo do {object:172982}.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders e os guardas caídos estão logo a sudoeste da torre. Pegue a pena de Raani e o sinete Cantonegro dos corpos.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De volta a {quest:92529}: Tempestários e {npc:251662} enchem a aldeia, os Baús de Suprimentos ficam entre as casas e {npc:251966} espera no extremo sudeste.",
		["Back to {area:16635}"] = "De volta a {area:16635}",
		["Back to {area:16638}"] = "De volta a {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Volte a {npc:268592}. Espere ele acender {npc:268762} e leve a chama direto para {npc:268679} ao lado de {npc:252382} em {area:16638} antes que o tempo acabe.",
		["Find {npc:258130}"] = "Encontre {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "Siga a estrada para o sul até {area:16624}, no meio da ilha.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Siga para o norte, entrando em {area:16631}; {npc:257944} acampa na borda sul.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Siga para sudoeste até {area:17674}. {npc:252155} está no topo; {item:254871} está ao lado dele.",
		["Heal the injured druids in the Nightfang Den"] = "Cure os druidas feridos no Nightfang Den",
		["Leaving {area:16635}"] = "Saindo de {area:16635}",
		["Listen to {npc:252448}'s story"] = "Ouça a história de {npc:252448}",
		["Listen to {npc:256083}"] = "Ouça {npc:256083}",
		["Northern {zone:1412}"] = "Norte de {zone:1412}",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Cirromoscas Irritantes e {npc:250873} vagam pelo bosque logo a sudeste da aldeia.",
		["Raw Windstones"] = "Pedras Eólicas Brutas",
		["Skyhoppers"] = "Saltacéus",
		["Skyhoppers hop about the fields just west of Valennia."] = "Saltacéus saltitam pelos campos logo a oeste de Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Espalhe {item:278078} a partir de {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Maçãs-dos-raios e pó de asaleve estão espalhados pelo pomar; Bandidos Famintos o saqueiam. Vagaventos pastam nos campos a leste dele. O constructo quebrado flutua na borda norte do pomar.",
		["Talk to {npc:251902}"] = "Fale com {npc:251902}",
		["Talk to {npc:251968}"] = "Fale com {npc:251968}",
		["Talk to {npc:252383}"] = "Fale com {npc:252383}",
		["Talk to {npc:252800}"] = "Fale com {npc:252800}",
		["Talk to {npc:253576}"] = "Fale com {npc:253576}",
		["Talk to {npc:254089}"] = "Fale com {npc:254089}",
		["Tell {npc:252800} you're ready"] = "Diga a {npc:252800} que você está pronto",
		["The Al'Aketh camp"] = "O acampamento Al'Aketh",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "As Pedras Eólicas Brutas são cristais azuis nas encostas em volta da aldeia.",
		["The orchard"] = "O pomar",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "A rainha paira no extremo sudeste do bosque, no caminho de volta dos monólitos.",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "Os pertences dos refugiados estão ao longo da margem norte de {area:16625}; {npc:259013} fica no extremo noroeste.",
		["The standing stones"] = "Os monólitos",
		["The turncoat"] = "O traidor",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "A casa do traidor fica em {area:16626}, a noroeste de {area:16638}. {npc:273017} espera por perto; seus assassinos espreitam em volta da casa.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} fica ao norte de {area:16638}. Abra caminho entre os guardas até {npc:253576}, no lado leste.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Use {item:278078} no tapete cerimonial e no incensário do penhasco voltado para o sul em {area:1641}.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Você deixa a ilha de vez. {npc:259119} espera onde o dirigível pousa.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Você acorda em {area:16635}, no norte da ilha. {npc:251362} fica junto ao caminho, e {npc:251361} no centro da aldeia.",
		["search the dead cultist in the house"] = "revistar o sectário morto na casa",
		["search the wardrobe"] = "revistar o guarda-roupa",
		["talk to {npc:251684}"] = "fale com {npc:251684}",
		["talk to {npc:251902}"] = "fale com {npc:251902}",
		["talk to {npc:251968}"] = "fale com {npc:251968}",
		["talk to {npc:252155}"] = "fale com {npc:252155}",
		["talk to {npc:252476}"] = "fale com {npc:252476}",
		["talk to {npc:257554}"] = "fale com {npc:257554}",
		["the bounty board"] = "o quadro de recompensas",
		["{area:16624} turn-ins"] = "Entregas em {area:16624}",
		["{area:16635} turn-ins"] = "Entregas em {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} fica a oeste de {area:16638}, pela estrada costeira.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} cresce em volta do acampamento de {npc:257944}, e Shriekings voam sobre ele. O acampamento Al'Aketh a leste dela guarda {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, de {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, de {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, de {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, de {npc:3027}",
		["{npc:251361}'s errands"] = "As tarefas de {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: um bilhete do seu instrutor",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: examine {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: leia {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, o instrutor de druidas, no térreo da árvore atrás de {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} e o seu {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, na torre de vigia",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, na torre de vigia",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, o seu {item:5176} e {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} e {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} e {npc:258134} estão no acampamento do culto a leste de {npc:257944}. {npc:254151} fica na borda. Haalien também deixa cair {quest:94490}: leia para iniciar a próxima missão. Para {quest:94489}, entre no Nightfang Den, cure 7 druidas feridos e encontre {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} espreita ao sul da aldeia, entre as Garraltivas. {npc:254589} é elite: recomenda-se formar grupo.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} fica em {area:16626}, logo a noroeste da cidade.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} espera na estrada ao norte de {area:16638}, na direção de {area:16629}.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} guarda {item:263993} no lado oeste do santuário.",
		["{npc:257944} again"] = "{npc:257944} de novo",
		["{npc:257944}, last time"] = "{npc:257944}, última vez",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, junto ao pouso: para {npc:3033} em {zone:1456}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}: guarde-a, Thrall em {zone:1454} vem dois guias depois",
		["{npc:263664}'s campfire"] = "A fogueira de {npc:263664}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} quer incenso tauren: compre as quatro partes de {npc:3014}, a herborista, {npc:3012}, a fornecedora de encantamento, {npc:3005}, o fornecedor de couraria, e {npc:3027}, o fornecedor de culinária, depois combine-as em {item:278078}.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} fica ao sul de Shen'dar. {npc:257065} encontra você na entrada; reviste o guarda-roupa na casa atrás dele.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Volte para leste até a {area:358}: os Xamãs Costagulha ficam entre os javatuscos de lá.",
		["Back south-east to the {area:396}."] = "Volte para sudeste até o {area:396}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Volte até {npc:5888} no acampamento. A {npc:5891} espera na mesa a leste do acampamento: beba a {item:6635} lá para vê-la, depois leve o {item:6656} de volta ao Vidente.",
		["Back west to the camp."] = "Volte para oeste até o acampamento.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Javaliços pastam ao norte do santuário; os javatuscos Costagulha ocupam a ravina a nordeste. {npc:8554} fica no extremo leste dela, e o {object:3076} está no chão do acampamento.",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Atravesse para noroeste, passando por {zone:1456}, até o {area:398}, no extremo norte de {zone:1412}.",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "Siga a trilha para o sul saindo do acampamento até a tenda do Vidente, no sopé das colinas.",
		["Galak centaurs"] = "Centauros Galath",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Siga para o norte até o {area:225}, a leste de {zone:1456}. {npc:3233} fica no pé das rochas; os Traiçoeiros Costagulha cavam no cemitério e o {npc:2994} espera no alto.",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Os Lobos-da-pradaria Alfa vagam entre os lobos nas planícies em volta de {npc:275789} e do acampamento Galath a leste.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Lobos-da-pradaria e Pinotes Adultos vagam pelas planícies em volta da aldeia.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Suba um elevador até as mesas. {npc:2995} cuida das serpes na elevação central; {npc:3057} fica na grande tenda de lá.",
		["Spread the {item:278078} off {area:1641}"] = "Espalhe o {item:278078} do alto do {area:1641}",
		["Swoops glide over the plains all around Bloodhoof."] = "Rapineiros planam sobre as planícies em volta de Casco Sangrento.",
		["Tame it with the {item:15908}"] = "Domestique-o com a {item:15908}",
		["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "Os centauros Galath acampam nas planícies a leste do poço; {npc:275767} os lidera.",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Os gnolls Jubalba ocupam a {area:818}, ao sul do sítio de escavação e a oeste de Casco Sangrento. {npc:272203} está preso no acampamento deles: leve-o para fora.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "As harpias Ventofúria ocupam o {area:819}, ao norte e a oeste do poço.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Os anões do {area:404} carregam as Picaretas do Prospector. Destrua-as na forja dos anões, no sítio de escavação.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Os goblins exploram a mina nas colinas a nordeste do poço. {quest:765} fica no fundo da mina; os {item:281031} dele iniciam {quest:98424}, e as outras páginas estão dentro da mina.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "O incenso se apaga em dez minutos: corra direto para o leste pelas colinas do sul até a {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "O santuário de An'she e Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "A pedra fica no desfiladeiro que sai de {zone:1412}, no seu caminho para o leste. Use o {item:15710} lá e derrote Lunagarra.",
		["The well lies south-east of the village."] = "O poço fica a sudeste da aldeia.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "A caravana destruída fica a noroeste dos centauros, a leste da estrada para {zone:1456}.",
		["The {object:177525}"] = "A {object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Use o {item:278078} no tapete cerimonial e no incensário do penhasco virado para o sul do {area:1641}.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Você começa na mesa da {area:221}. {npc:2980} e o chefe ficam junto à grande tenda no centro.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, de {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, de {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, de {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, de {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, na forja do sítio de escavação",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}: Predadores das Estepes vagam pelas planícies em volta do {area:225}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} quer incenso tauren: compre as quatro partes de {npc:3014}, a herborista, {npc:3012}, a fornecedora de encantamento, {npc:3005}, a fornecedora de couraria, e {npc:3027}, o fornecedor de culinária, depois combine-as em {item:278078}.",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "{npc:275789} fica nas {area:821}, um pouco a leste do poço.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} fica na borda norte da aldeia. Kyle quer {item:287505} de pinotes.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, no extremo norte da aldeia",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, para Hamuul em {zone:1456}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} fica na borda do {area:404}, ao sul do poço.",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988} acampa junto ao {area:396}, a sudeste de Casco Sangrento.",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} fica sentada junto à tenda na borda leste do acampamento; {object:2907} está ao lado dela.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, para {npc:3057} em {zone:1456}",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, o instrutor de druida ao lado dele",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, a instrutora de caçador",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, a instrutora de xamã no acampamento",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Missão de {npc:3063}: vença três Guerreiros Novatos (ou jogadores em duelos) ao lado dele.",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}: para {quest:860} em {area:380}",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}: para {npc:3448} em {area:380}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} fica na {area:221}. {quest:1516} requer nível 4, que você alcança com as entregas daqui.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} e o seu {item:5175}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775} fica no extremo oeste do acampamento, no canto noroeste das colinas onde rondam os Pumas da Montanha: pegue a missão dele, cace os pumas dali para o sul e o leste e depois volte até {npc:2980}.",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, um lobo solitário, ronda as planícies a oeste da aldeia. Espreitadores-da-pradaria e Pumas das Estepes vagam pelas planícies ao norte e a oeste dela.",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Volte para leste até a praia ao norte de {npc:275657}. Batedores Iralisca e Serviçais Iralisca ocupam a praia abaixo da {area:370}. Caçadores: domestiquem um {npc:3107} na praia.",
		["Back south to {area:362}."] = "Volte para o sul até {area:362}.",
		["Back to the Den"] = "De volta ao Covil",
		["Back to {area:362}."] = "De volta a {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Volte até {npc:5875} na {object:172960}. Use os {item:7464} no círculo de evocação de lá e derrote o emissário do caos para prendê-lo.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Sectários de Lâmina Ardente ocupam as cavernas de {quest:827}; qualquer um deles deixa cair um {item:4871}. {npc:3204}, um bruxo de nível 14, fica no fundo e deixa cair o {item:4903}.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Os Espreitadores Vis vagam pela encosta abaixo da caverna, no lado norte do vale.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Siga a estrada para leste saindo do vale até a {area:367}, na costa.",
		["Free {npc:275811} and see her safely out of the crag"] = "Liberte {npc:275811} e leve-a em segurança para fora do penedo",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dentro da caverna, siga reto na primeira bifurcação, depois à direita, e acompanhe o riacho à sua esquerda até a cachoeira: a picareta brilha junto à água, atrás de uma coluna de pedra.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dentro da caverna, mantenha-se rente à parede da direita a volta toda, passando o riacho: {npc:3183} espera no fim.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "A cabana de Misha fica ao sul dos lagartos. Os crocoliscos ao longo do {area:814}, a oeste, carregam o {item:4891}.",
		["Prickly pears"] = "Figos-da-índia",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Javatuscos e batedores ocupam as cabanas a oeste da cidade; levanta-poeiras e guardas de batalha ocupam os acampamentos mais a oeste.",
		["Spitelash naga"] = "Nagas Iralisca",
		["Tame it with the {item:15908}"] = "Domestique-o com a {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "A fortaleza fica na costa a sudeste de {area:362}. O machado, o arco e o escudo dos saqueadores estão nos arredores dela. Marinheiros e fuzileiros derrubam os {item:4870}. {npc:3192} espera no alto da fortaleza; a chave dele abre o baú ao seu lado, que guarda o {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Os figos-da-índia crescem entre as cabanas dos javatuscos logo a oeste da cidade.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "As armas ficam em volta d'O Covil e do campo de treino; os Mosquetuscos vagam por todo o fundo do vale.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "O {object:58595} fica na {area:817}, entre os sectários que você acabou de enfrentar.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Lagartos Trovejantes e Pelegos de Relâmpago pastam no {area:369}, do outro lado da ponte; qualquer um deles pode derrubar uma {item:6486}.",
		["Thunder lizards across the river"] = "Lagartos trovejantes do outro lado do rio",
		["Training weapons and boars"] = "Armas de treino e javalis",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "Atravesse a água até a ilha mais ao norte das Ilhas do Eco. A Matriarca ronda entre os raptores de lá.",
		["Wake {quest:5441} with the {item:16114}"] = "Acorde os {quest:5441} com o {item:16114}",
		["the {object:654925} on the ground beside her"] = "o {object:654925} no chão ao lado dela",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "O {area:366} fica a oeste de Sen'jin. Os três planos de ataque estão no chão entre as tendas dos centauros. {npc:275811} também está presa no penedo.",
		["{area:817}'s mouth"] = "Entrada da {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, onde você começa",
		["{npc:265809}'s campfire"] = "A fogueira de {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: só encantadores, o resíduo vem do desencantamento de Pingentes Bagateados",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} fica na praia a leste de {area:362}. O tridente, o estandarte e a adaga estão na areia em volta dele.",
		["{npc:3102} hooves"] = "Cascos de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de volta em {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, um gigante do mar elite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} fica logo na entrada da caverna; {npc:3159}, no fundo da caverna, atrás dele.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} espera dentro d'O Covil, a construção logo a oeste de {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, na torre de vigia",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} está ferido no sopé das colinas a noroeste d'O Covil.",
		["{npc:3294}, by the inn"] = "{npc:3294}, junto à estalagem",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, para {npc:6018} em {zone:1454}: guarde-a",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, o instrutor de sacerdote n'O Covil",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} fica do lado de fora d'O Covil. {area:639} é a colina logo ao sul: beba a {item:6635} lá para ver a {npc:5891}, depois leve o {item:6656} de volta para {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} e o seu {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, na {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} fica na estrada, na saída leste do vale.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, junto à fogueira de cozinhar",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} acampa na colina a oeste da praia dos nagas, ao sul da {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "O portão principal de {zone:1454} fica logo a oeste da {area:817}. {npc:5875} fica na {object:172960}, o cânion abaixo do {object:172982}.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["Ask {npc:10666} for his report"] = "Peça o relatório a {npc:10666}",
		["Ask {npc:1496} for his report"] = "Peça o relatório a {npc:1496}",
		["Ask {npc:251001} for his report"] = "Peça o relatório a {npc:251001}",
		["Back to the church"] = "De volta à igreja",
		["Back to {area:154}"] = "De volta a {area:154}",
		["Back up the road to {area:159}."] = "Volte pela estrada até {area:159}.",
		["Beat {npc:6784} in the duel"] = "Vença {npc:6784} no duelo",
		["Crusader's Outpost"] = "Posto avançado dos Cruzados",
		["Dry Branches"] = "Galhos Secos",
		["Eleanor camps just south-west of town."] = "Eleonora acampa logo a sudoeste da cidade.",
		["Escort {npc:275954} out of the outpost"] = "Escolte {npc:275954} para fora do posto avançado",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "Siga a trilha para o norte até {area:154}; Sarvis fica em frente à igreja.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "Siga a estrada para sudeste a partir de {area:159}, passando as torres de zepelim. Lina, Kristof e {npc:3549} acampam junto à estrada.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "Siga a estrada para sudoeste a partir de {area:159} até o acampamento da Cruzada Escarlate. {npc:1662} fica no extremo sul; todo Escarlate de lá pode deixar cair um anel.",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}."] = "Saia de {area:154} pela estrada a nordeste. {npc:6784} fica perto da casa da {area:156}.",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "Ouça Leonid e {npc:246378}, depois fale com ele de novo",
		["Mindless Zombies"] = "Zumbis Desmiolados",
		["More Vile Fin murlocs walk the shore just north of the outpost."] = "Mais murlocs Pinavil andam pela margem logo ao norte do posto avançado.",
		["Offer aid to the {npc:246143}"] = "Ofereça ajuda ao {npc:246143}",
		["Only if the letter dropped"] = "Só se a carta tiver caído",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side."] = "Esqueletos Range-ossos vagam pelas casas em ruínas na metade norte de {area:154}. Carniceiros Jovens e Quiropúsculos vagam por toda a vila; os Carniceiros Rotos e os Quiropúsculos Sarnentos ficam no lado leste.",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "Os Galhos Secos ficam no chão em volta da borda sudoeste de {area:159}.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "Os Neófitos e Iniciados Escarlates ocupam a fazenda a leste de {area:154}. {npc:1919} anda entre as casas da fazenda: os restos dele são para {quest:6395}.",
		["The Scarlet farm"] = "A fazenda Escarlate",
		["The Wanted poster by the inn"] = "O cartaz de procura-se perto da estalagem",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "Os zumbis se arrastam pelo cemitério e pelas casas logo a leste da igreja.",
		["The {area:154} trainers stand around the church"] = "Os instrutores de {area:154} ficam em volta da igreja",
		["The {area:159} trainers are in and around the inn"] = "Os instrutores de {area:159} ficam dentro e em volta da estalagem",
		["The {npc:1931}, in the town hall basement"] = "O {npc:1931}, no porão da prefeitura",
		["The {npc:2211}, in the town hall basement"] = "O {npc:2211}, no porão da prefeitura",
		["The {npc:246143}"] = "O {npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "As {object:164662} ficam ao lado das casas em ruínas no norte de {area:154}.",
		["Tirisfal Pumpkins"] = "Abóboras de Tirisfal",
		["Use the {item:286176} on five idle Deathguards around town"] = "Use o {item:286176} em cinco Necroguardas ociosos pela cidade",
		["Vile Fin shore"] = "Margem dos Pinavil",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Ande para o sul de {area:159} até as {area:153} e desça até {zone:1458}. {npc:4568} fica no {object:36082}. O acampamento Escarlate fica logo a oeste das ruínas.",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Ande para o sul de {area:159} até as {area:153} e desça até {zone:1458}. {npc:5675} fica no {object:36082}. O acampamento Escarlate fica logo a oeste das ruínas.",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "Você se levanta na cripta no extremo sul de {area:154}. {npc:1568} espera logo do lado de fora.",
		["{item:16333}, from {npc:1919}"] = "{item:16333}, de {npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "{item:2320} de {npc:2118}, para Gretchen",
		["{item:2839}, a rare drop"] = "{item:2839}, item raro",
		["{item:7227}, in the farmstead's garden"] = "{item:7227}, na horta da fazenda",
		["{npc:1495}'s camp"] = "Acampamento de {npc:1495}",
		["{npc:1496} stands in {area:159}. {npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "{npc:1496} fica em {area:159}. {npc:6390} espera no mausoléu na colina logo ao norte da cidade: abra o portão e lute com ele.",
		["{npc:1499}, in the town hall"] = "{npc:1499}, na prefeitura",
		["{npc:1500}, in the inn"] = "{npc:1500}, na estalagem",
		["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Darkhounds roam a little further west, toward {npc:10666}."] = "{npc:1525} e Cadáveres Assolados se arrastam pelos campos logo a oeste de {area:159}; Cães das Trevas vagam um pouco mais a oeste, rumo a {npc:10666}.",
		["{npc:1560}, in the inn"] = "{npc:1560}, na estalagem",
